fn csharpIdent(name: &str) -> String {
    match name {
        "Self_" => "Self".to_string(),
        "self_" => "self".to_string(),
        "super_" => "super".to_string(),
        "crate_" => "crate".to_string(),
        other => other.to_string(),
    }
}

fn nameOf<T: std::fmt::Debug>(value: T) -> String {
    csharpIdent(&format!("{value:?}"))
}

/// C# `Enum.GetName` for a `[Flags]` enum: the name of the member whose value
/// is exactly `bits`, or `None`. The first declared member wins a shared value.
fn flagName<T>(bits: T::Bits) -> Option<String>
where
    T: Flags,
    T::Bits: PartialEq + Copy,
{
    T::FLAGS.iter()
        .find(|f| !f.name().is_empty() && f.value().bits() == bits)
        .map(|f| csharpIdent(f.name()))
}

/// `DateTimeOffset.FromUnixTimeSeconds(value).DateTime.ToString(InvariantCulture)`.
/// Invariant "G" is `MM/dd/yyyy HH:mm:ss`. The offset is zero, so the clock is UTC.
fn unixSecondsToInvariant(value: i32) -> String {
    let secs = value as i64;
    let days = secs.div_euclid(86_400);
    let sod = secs.rem_euclid(86_400) as u32;
    let hour = sod / 3600;
    let minute = (sod % 3600) / 60;
    let second = sod % 60;
    let (year, month, day) = civilFromDays(days);
    format!("{month:02}/{day:02}/{year:04} {hour:02}:{minute:02}:{second:02}")
}

fn civilFromDays(days: i64) -> (i32, u32, u32) {
    // Howard Hinnant. Every i32 unix second is after year 0, so `z` stays positive
    // and truncating division matches the algorithm.
    let z = days + 719_468;
    let era = (if z >= 0 { z } else { z - 146_096 }) / 146_097;
    let doe = (z - era * 146_097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    let mut year = yoe as i64 + era * 400;
    if month <= 2 {
        year += 1;
    }
    (year as i32, month as u32, day as u32)
}

