impl PropertyDataId {
    /// C# `GetValueEnumName`. `None` where `Enum.GetName` returns null.
    pub fn getValueEnumName(self, value: u32) -> Option<String> {
        match self {
            Self::ActivationAnimation | Self::InitMotion | Self::UseTargetAnimation | Self::UseTargetFailureAnimation | Self::UseTargetSuccessAnimation | Self::UseUserAnimation => MotionCommand::fromRaw(value).map(nameOf),
            Self::PhysicsScript | Self::RestrictionEffect => PlayScript::fromRaw(value).map(nameOf),
            Self::ActivationSound | Self::UseSound => Sound::fromRaw(value).map(nameOf),
            Self::WieldedTreasureType | Self::DeathTreasureType => None,
            Self::Spell | Self::DeathSpell | Self::ProcSpell | Self::RedSurgeSpell | Self::BlueSurgeSpell | Self::YellowSurgeSpell => SpellId(value).name().map(csharpIdent),
            Self::ItemSkillLimit | Self::ItemSpecializedOnly => i32::try_from(value).ok().and_then(Skill::fromRaw).map(nameOf),
            Self::PCAPRecordedParentLocation => i32::try_from(value).ok().and_then(ParentLocation::fromRaw).map(nameOf),
            Self::PCAPRecordedDefaultScript => MotionCommand::fromRaw(value).map(nameOf),
            _ => None,
        }
    }

    pub fn isHexData(self) -> bool {
        match self {
            Self::AccountHouseId | Self::AlternateCurrency | Self::AugmentationCreateItem | Self::AugmentationEffect | Self::BlueSurgeSpell | Self::DeathSpell | Self::DeathTreasureType | Self::HouseId | Self::ItemSkillLimit | Self::ItemSpecializedOnly | Self::LastPortal | Self::LinkedPortalOne | Self::LinkedPortalTwo | Self::OlthoiDeathTreasureType | Self::OriginalPortal | Self::PhysicsScript | Self::ProcSpell | Self::RedSurgeSpell | Self::RestrictionEffect | Self::Spell | Self::SpellComponent | Self::UseCreateItem | Self::UseSound | Self::VendorsClassId | Self::WieldedTreasureType | Self::YellowSurgeSpell => false,
            value if value.toRaw() >= Self::PCAPRecordedWeenieHeader.toRaw() => false,
            _ => true,
        }
    }
}

